633	    private void updateSection(BrowseSection section) {
634	        switch (section.getType()) {
635	            case BrowseSection.TYPE_GRID:
636	            case BrowseSection.TYPE_SHORTS_GRID:
637	                if (mGridMapping.containsKey(section.getId())) {
638	                    Observable<MediaGroup> group = mGridMapping.get(section.getId());
639	                    updateVideoGrid(section, group, section.isAuthOnly());
640	                } else if (mLocalGridMappings.containsKey(section.getId())) {
641	                    Callable<List<Video>> localVideos = mLocalGridMappings.get(section.getId());
642	                    updateLocalGrid(section, localVideos);
643	                }
644	                break;
645	            case BrowseSection.TYPE_ROW:
646	                Observable<List<MediaGroup>> groups = mRowMapping.get(section.getId());
647	                updateVideoRows(section, groups, section.isAuthOnly());
648	                break;
649	            case BrowseSection.TYPE_SETTINGS_GRID:
650	                Callable<List<SettingsItem>> items = mSettingsGridMapping.get(section.getId());
651	                updateSettingsGrid(section, items);
652	                break;
653	            case BrowseSection.TYPE_MULTI_GRID:
654	                Observable<MediaGroup> group2 = mGridMapping.get(section.getId());
655	                updateVideoGrid(section, group2, 0, section.isAuthOnly());
656	                break;
657	            case BrowseSection.TYPE_ERROR:
658	                getView().showProgressBar(false);
659	                break;
660	        }
661	
662	        updateRefreshTime();
663	    }
