695	    private void updateVideoRows(BrowseSection section, Observable<List<MediaGroup>> groups) {
696	        Log.d(TAG, "updateRowsHeader: Start loading section: " + section.getTitle());
697	
698	        disposeActions();
699	
700	        if (getView() == null) {
701	            Log.e(TAG, "Browse view has been unloaded from the memory. Low RAM?");
702	            getViewManager().startView(BrowseView.class);
703	            return;
704	        }
705	        
706	        getView().showProgressBar(true);
707	
708	        VideoGroup firstGroup = VideoGroup.from(section);
709	        firstGroup.setAction(VideoGroup.ACTION_REPLACE);
710	        getView().updateSection(firstGroup);
711	
712	        if (groups == null) {
713	            // No group. Maybe just clear.
714	            getView().showProgressBar(false);
715	            return;
716	        }
717	
718	        AtomicInteger groupIndex = new AtomicInteger(-1);
719	
720	        Disposable updateAction = groups
721	                .subscribe(
722	                        mediaGroups -> {
723	                            getView().showProgressBar(false);
724	
725	                            filterHomeIfNeeded(mediaGroups);
726	
727	                            for (MediaGroup mediaGroup : mediaGroups) {
728	                                if (mediaGroup.isEmpty()) {
729	                                    Log.e(TAG, "loadRowsHeader: MediaGroup is empty. Group Name: " + mediaGroup.getTitle());
730	                                    continue;
731	                                }
732	
733	                                VideoGroup videoGroup = VideoGroup.from(mediaGroup, section, groupIndex.incrementAndGet());
734	
735	                                if (TextUtils.isEmpty(videoGroup.getTitle())) {
736	                                    videoGroup.setTitle(getContext().getString(R.string.suggestions));
737	                                }
738	
739	                                getView().updateSection(videoGroup);
740	                                mBrowseProcessor.process(videoGroup);
741	
742	                                continueGroupIfNeeded(videoGroup, false);
743	                            }
744	                        },
745	                        error -> {
746	                            Log.e(TAG, "updateRowsHeader error: %s", error.getMessage());
747	                            handleLoadError(error);
748	                        }, () -> handleLoadError(null));
749	
750	        mActions.add(updateAction);
751	    }
