421	            case PlayerConstants.PLAYBACK_MODE_ALL:
422	            case PlayerConstants.PLAYBACK_MODE_SHUFFLE:
423	                loadNext();
424	                break;
425	            case PlayerConstants.PLAYBACK_MODE_ONE:
426	                if (VERSION.SDK_INT <= 19) {
427	                    // Fix frozen image on Android 4
428	                    restartEngine();
429	                } else {
430	                    getPlayer().setPositionMs(0);
431	                }
432	                break;
433	            case PlayerConstants.PLAYBACK_MODE_CLOSE:
434	                // Close player if suggestions not shown
435	                // Except when playing from queue
436	                if (mPlaylist.getNext() != null && !getPlayerTweaksData().isQueueRespectsPlaybackMode()) {
437	                    loadNext();
438	                } else {
439	                    AppDialogPresenter dialog = getAppDialogPresenter();
440	                    if (!getPlayer().isSuggestionsShown() && (!dialog.isDialogShown() || dialog.isOverlay())) {
441	                        dialog.closeDialog();
442	                        getPlayer().finishReally();
443	                    }
444	                }
445	                break;
446	            case PlayerConstants.PLAYBACK_MODE_PAUSE:
447	                // Stop player after each video.
448	                // Except when playing from queue
449	                if (mPlaylist.getNext() != null && !getPlayerTweaksData().isQueueRespectsPlaybackMode()) {
450	                    loadNext();
451	                } else {
452	                    stopPlayback();
453	                }
454	                break;
455	            case PlayerConstants.PLAYBACK_MODE_LIST:
456	                // if video has a playlist load next or restart playlist
457	                if (video.hasNextPlaylist() || mPlaylist.getNext() != null) {
458	                    loadNext();
459	                } else {
460	                    //restartPlaylistIfNeeded();
461	                    stopPlayback();
462	                }
463	                break;
464	            default:
465	                Log.e(TAG, "Undetected repeat mode " + playbackMode);
466	                break;
